CREATE TABLE payments AS
  SELECT g AS id, 'card-' || (g % 5000) AS card, (g % 997) * 100 AS amount_cents
  FROM generate_series(1, 1000000) g;
VACUUM ANALYZE payments;
SELECT pg_relation_size('payments') / 8192 AS heap_pages;
SET max_parallel_workers_per_gather = 0;

EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF) SELECT * FROM payments WHERE id = 424242;

ALTER TABLE payments ADD PRIMARY KEY (id);
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF) SELECT * FROM payments WHERE id = 424242;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF) SELECT * FROM payments WHERE id = 424242;
SELECT pg_relation_size('payments_pkey') / 8192 AS index_pages;

SELECT root, level FROM bt_metap('payments_pkey');

SELECT itemoffset, ctid, data
FROM bt_page_items('payments_pkey', (SELECT root FROM bt_metap('payments_pkey')))
LIMIT 3;

SELECT blkno, type, live_items, free_size, btpo_next FROM bt_page_stats('payments_pkey', 1);
SELECT itemoffset, ctid, data FROM bt_page_items('payments_pkey', 1) LIMIT 3;

SELECT type, count(*) AS pages, round(avg(live_items)) AS avg_items
FROM bt_multi_page_stats('payments_pkey', 1, -1) GROUP BY type ORDER BY type;

CREATE TABLE auths (id int PRIMARY KEY);
INSERT INTO auths SELECT generate_series(1, 407);
SELECT root, level, pg_relation_size('auths_pkey') / 8192 AS pages FROM bt_metap('auths_pkey');

INSERT INTO auths VALUES (408);
SELECT root, level, pg_relation_size('auths_pkey') / 8192 AS pages FROM bt_metap('auths_pkey');
SELECT blkno, type, live_items, btpo_prev, btpo_next FROM bt_multi_page_stats('auths_pkey', 1, -1);
SELECT itemoffset, ctid, data FROM bt_page_items('auths_pkey', 3);

CREATE EXTENSION IF NOT EXISTS pgstattuple;
CREATE TABLE ids_v7 (id uuid PRIMARY KEY);
CREATE TABLE ids_v4 (id uuid PRIMARY KEY);
INSERT INTO ids_v7 SELECT uuidv7() FROM generate_series(1, 200000);
INSERT INTO ids_v4 SELECT gen_random_uuid() FROM generate_series(1, 200000);
SELECT 'ids_v7' AS t, leaf_pages, avg_leaf_density FROM pgstatindex('ids_v7_pkey')
UNION ALL
SELECT 'ids_v4', leaf_pages, avg_leaf_density FROM pgstatindex('ids_v4_pkey');

EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF) SELECT * FROM payments WHERE id BETWEEN 1000 AND 1999;

CREATE TABLE settlements AS
  SELECT g AS id, g % 4 AS region, g / 4 AS batch_id, (g % 997) * 100 AS amount_cents
  FROM generate_series(1, 1000000) g;
CREATE INDEX settlements_region_batch ON settlements (region, batch_id);
VACUUM ANALYZE settlements;

EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF) SELECT region, batch_id FROM settlements WHERE batch_id = 7700;
EXPLAIN (ANALYZE, COSTS OFF, TIMING OFF) SELECT region, batch_id FROM settlements WHERE region = 2 AND batch_id = 7700;

