fun levels(rows: Long, perLeaf: Int = 366, fanout: Int = 274): Int {
    var pages = (rows + perLeaf - 1) / perLeaf   // leaves
    var levels = 1
    while (pages > 1) {                          // add a level until one page holds it all
        pages = (pages + fanout - 1) / fanout
        levels++
    }
    return levels
}

// levels(1_000_000) = 3, levels(100_000_000) = 4, levels(10_000_000_000) = 5
